import java.io.*;

public class Main {
    public static final int MOD = 998244353;

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = nextInt(in);
        int[] head = new int[n + 1];
        java.util.Arrays.fill(head, -1);
        int m = Math.max(1, 2 * (n - 1));
        int[] nxt = new int[m];
        int[] to = new int[m];
        int cnt = 0;
        for (int i = 0; i < n - 1; i++) {
            int u = nextInt(in);
            int v = nextInt(in);
            to[cnt] = v; nxt[cnt] = head[u]; head[u] = cnt++;
            to[cnt] = u; nxt[cnt] = head[v]; head[v] = cnt++;
        }

        int[] order = new int[n];
        int[] parent = new int[n + 1];
        int qh = 0, qt = 0;
        order[qt++] = 1;
        parent[1] = 0;
        boolean[] vis = new boolean[n + 1];
        vis[1] = true;
        while (qh < qt) {
            int v = order[qh++];
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int u = to[e];
                if (!vis[u]) {
                    vis[u] = true;
                    parent[u] = v;
                    order[qt++] = u;
                }
            }
        }

        long[] dp0 = new long[n + 1];
        long[] dp1 = new long[n + 1];
        long[] dp1s = new long[n + 1];

        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            long X = 0, Y = 1, S = 1;
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int c = to[e];
                if (c == parent[v]) continue;
                long cut = (dp0[c] + dp1s[c]) % MOD;
                long ku = dp0[c];
                long base = (cut + ku) % MOD;
                long nX = (X * base + Y * dp1[c]) % MOD;
                long nY = (Y * base) % MOD;
                X = nX;
                Y = nY;
                S = (S * cut) % MOD;
            }
            dp0[v] = X;
            dp1[v] = Y;
            dp1s[v] = S;
        }

        long ans = (dp0[1] + dp1s[1]) % MOD;
        System.out.println(ans);
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int ret = 0;
        int b = in.read();
        while (b < '0' || b > '9') {
            if (b == -1) return -1;
            b = in.read();
        }
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = in.read();
        }
        return ret;
    }
}
