    static int[] tree;
    static int N;
    static void update(int i, int v){ for(i++; i<=N; i+=i&(-i)) if(tree[i]<v) tree[i]=v; }
    static int query(int i){ int r=0; for(i++; i>0; i-=i&(-i)) if(tree[i]>r) r=tree[i]; return r; }

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in));
        int n = nextInt(in), m = nextInt(in);
        int[] diff = new int[m+2];
        for(int i=0;i<n;i++){
            int l = nextInt(in), r = nextInt(in);
            diff[l]++; diff[r+1]--;
        }
        int[] a = new int[m+1];
        int cur=0;
        for(int i=1;i<=m;i++){ cur+=diff[i]; a[i]=cur; }
        N = n+2;
        int[] f = new int[m+2];
        int[] g = new int[m+2];
        tree = new int[N+1];
        for(int i=1;i<=m;i++){
            f[i] = query(a[i]) + 1;
            update(a[i], f[i]);
        }
        tree = new int[N+1];
        for(int i=m;i>=1;i--){
            g[i] = query(a[i]) + 1;
            update(a[i], g[i]);
        }
        int ans=0;
        for(int i=1;i<=m;i++){
            int v = f[i]+g[i]-1;
            if(v>ans) ans=v;
        }
        System.out.println(ans);
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int ret = 0;
        int b = in.read();
        while(b < '0') b = in.read();
        boolean neg=false;
        if(b=='-'){neg=true;b=in.read();}
        while(b >= '0'){ ret = ret*10 + (b-'0'); b = in.read(); }
        return neg?-ret:ret;
