public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = nextInt(in);
        int k = nextInt(in);
        final int MOD = 1000000007;

        int size = Math.max(n + 2, 3);
        long[] inv = new long[size];
        inv[1] = 1;
        for (int i = 2; i < size; i++) {
            inv[i] = (MOD - (MOD / i) * inv[(int) (MOD % i)] % MOD) % MOD;
        }

        long[] t = new long[n + 1];
        long[] P = new long[n + 1];
        t[1] = 1;
        P[1] = 1;
        for (int m = 2; m <= n; m++) {
            int lo = Math.max(1, m - k);
            long s = (P[m - 1] - P[lo - 1] + MOD) % MOD;
            t[m] = s * inv[m - 1] % MOD;
            P[m] = (P[m - 1] + t[m]) % MOD;
        }

        long factNm1 = 1;
        for (int i = 1; i <= n - 1; i++) {
            factNm1 = factNm1 * i % MOD;
        }
        long factN = factNm1 * (n % MOD) % MOD;

        long good = factNm1 * P[n] % MOD;
        long ans = (factN - good % MOD + MOD) % MOD;
        System.out.println(ans);
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int ret = 0;
        int b = in.read();
        while (b < '0' || b > '9') {
            b = in.read();
        }
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = in.read();
        }
        return ret;
    }
}
