import java.util.*;
import java.math.BigInteger;

public class Main {
    static List<long[]> entries;

    static long solve(long rem, long minP) {
        if (rem == 1) return 1;
        long ans = 0;
        for (long[] e : entries) {
            long d = e[0];
            if (d > rem) break;
            if (rem % d == 0) {
                for (int i = 1; i < e.length; i++) {
                    if (e[i] >= minP) {
                        ans += solve(rem / d, e[i] + 1);
                    }
                }
            }
        }
        return ans;
    }

    static boolean isPrime(long n) {
        if (n < 2) return false;
        return BigInteger.valueOf(n).isProbablePrime(35);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long A = sc.nextLong();
        if (A == 1) {
            System.out.println(1);
            return;
        }
        // factor A
        long tmp = A;
        List<long[]> fac = new ArrayList<>();
        for (long p = 2; p * p <= tmp; p++) {
            if (tmp % p == 0) {
                int c = 0;
                while (tmp % p == 0) { tmp /= p; c++; }
                fac.add(new long[]{p, c});
            }
        }
        if (tmp > 1) fac.add(new long[]{tmp, 1});
        // divisors
        List<Long> divsList = new ArrayList<>();
        divsList.add(1L);
        for (long[] f : fac) {
            int sz = divsList.size();
            long pw = 1;
            List<Long> add = new ArrayList<>();
            for (int e = 1; e <= f[1]; e++) {
                pw *= f[0];
                for (int i = 0; i < sz; i++) {
                    add.add(divsList.get(i) * pw);
                }
            }
            divsList.addAll(add);
        }
        Collections.sort(divsList);
        HashSet<Long> divSet = new HashSet<>(divsList);
        HashMap<Long, List<Long>> map = new HashMap<>();

        int LIM = 1000000;
        boolean[] comp = new boolean[LIM + 1];
        for (int i = 2; (long) i * i <= LIM; i++) {
            if (!comp[i]) {
                for (int j = i * i; j <= LIM; j += i) comp[j] = true;
            }
        }
        for (int p = 2; p <= LIM; p++) {
            if (comp[p]) continue;
            long pw = p;
            long s = 1 + p;
            while (true) {
                if (pw > A / p) break;
                pw *= p;
                if (s > A - pw) { s = A + 1; }
                else s += pw;
                if (s > A) break;
                if (divSet.contains(s)) {
                    map.computeIfAbsent(s, k -> new ArrayList<>()).add((long) p);
                }
            }
        }
        for (long d : divsList) {
            if (d > 1) {
                long cand = d - 1;
                if (cand >= 2 && isPrime(cand)) {
                    map.computeIfAbsent(d, k -> new ArrayList<>()).add(cand);
                }
            }
        }
        entries = new ArrayList<>();
        for (long d : divsList) {
            List<Long> lst = map.get(d);
            if (lst != null && !lst.isEmpty()) {
                long[] e = new long[lst.size() + 1];
                e[0] = d;
                for (int i = 0; i < lst.size(); i++) e[i + 1] = lst.get(i);
                entries.add(e);
            }
        }
        entries.sort((a, b) -> Long.compare(a[0], b[0]));

        System.out.println(solve(A, 2));
    }
