public class Main {
    static final long MOD = 998244353L;

    static long power(long b, long e) {
        b %= MOD;
        if (b < 0) b += MOD;
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long l = Long.parseLong(st.nextToken());

        int N = 2 * n;
        long[] fact = new long[N + 2];
        long[] invFact = new long[N + 2];
        fact[0] = 1;
        for (int i = 1; i <= N + 1; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N + 1] = power(fact[N + 1], MOD - 2);
        for (int i = N + 1; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long[] df = new long[N + 1];
        df[0] = 1;
        for (int m = 2; m <= N; m += 2) {
            df[m] = df[m - 2] * (m - 1) % MOD;
        }
        if (N >= 1) {
            for (int m = 1; m <= N; m += 2) df[m] = 0;
        }

        long ans = 0;
        for (int i = 0; i <= N; i++) {
            int mmax = Math.min(i, N - i);
            int start = k;
            if (((i - start) & 1) != 0) start++;
            for (int t = start; t <= mmax; t += 2) {
                long term = fact[i] % MOD * invFact[t] % MOD * invFact[i - t] % MOD;
                term = term * fact[N - i] % MOD * invFact[t] % MOD * invFact[N - i - t] % MOD;
                term = term * fact[t] % MOD;
                term = term * df[i - t] % MOD;
                term = term * df[N - i - t] % MOD;
                ans += term;
                if (ans >= MOD) ans -= MOD;
            }
        }

        ans = ans % MOD * power(N + 1, MOD - 2) % MOD;
        ans = ans * power(df[N], MOD - 2) % MOD;
        ans = ans * (l % MOD) % MOD;

        System.out.println(ans);
    }
}
