import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in));
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int n = (int) st.nval;
        st.nextToken(); long m = (long) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = ((long) st.nval) % m; }

        int n1 = n / 2;
        int n2 = n - n1;

        long[] A = gen(a, 0, n1, m);
        long[] B = gen(a, n1, n2, m);

        Arrays.sort(B);
        // dedupe B
        int len = 0;
        for (int i = 0; i < B.length; i++) {
            if (i == 0 || B[i] != B[i-1]) B[len++] = B[i];
        }

        long ans = 0;
        long maxB = B[len-1];
        for (int i = 0; i < A.length; i++) {
            long x = A[i];
            // find largest y with y < m - x
            long target = m - x;
            int lo = 0, hi = len - 1, best = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (B[mid] < target) { best = mid; lo = mid + 1; }
                else hi = mid - 1;
            }
            if (best >= 0) {
                long v = x + B[best];
                if (v > ans) ans = v;
            }
            long v2 = x + maxB;
            if (v2 >= m) v2 -= m;
            if (v2 > ans) ans = v2;
        }
        System.out.println(ans);
    }

    static long[] gen(long[] a, int start, int cnt, long m) {
        int total = 1 << cnt;
        long[] res = new long[total];
        res[0] = 0;
        for (int i = 1; i < total; i++) {
            int lowbit = Integer.numberOfTrailingZeros(i);
            long v = res[i & (i-1)] + a[start + lowbit];
            if (v >= m) v -= m;
            res[i] = v;
        }
        return res;
    }
}
