            if (p > LIM / x) break;
            p = p * x;
        }
        p = 1;
        while (true) {
            py.add(p);
            if (p > LIM / y) break;
            p = p * y;
        }
        ArrayList<Long> sums = new ArrayList<>();
        for (long a : px) {
            for (long b : py) {
                long s = a + b;
                if (s < 0) continue;
                if (s >= l && s <= r) sums.add(s);
            }
        }
        Collections.sort(sums);
        long ans = 0;
        long prev = l;
        for (long s : sums) {
            if (s - prev > ans) ans = s - prev;
            if (s + 1 > prev) prev = s + 1;
        }
        if (r - prev + 1 > ans) ans = r - prev + 1;
        if (ans < 0) ans = 0;
        System.out.println(ans);
    }
