    static int best = 0;
    static int[] lab;

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in));
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); n = (int) st.nval;
        st.nextToken(); m = (int) st.nval;
        ea = new int[m]; eb = new int[m];
        for (int i = 0; i < m; i++) {
            st.nextToken(); ea[i] = (int) st.nval - 1;
            st.nextToken(); eb[i] = (int) st.nval - 1;
        }
        lab = new int[n];
        rec(0);
        System.out.println(best);
    }

    static void rec(int idx) {
        if (idx == n) {
            boolean[][] used = new boolean[7][7];
            int cnt = 0;
            for (int i = 0; i < m; i++) {
                int a = lab[ea[i]], b = lab[eb[i]];
                int x = Math.min(a, b), y = Math.max(a, b);
                if (!used[x][y]) { used[x][y] = true; cnt++; }
            }
            if (cnt > best) best = cnt;
            return;
        }
        for (int v = 1; v <= 6; v++) {
            lab[idx] = v;
            rec(idx + 1);
        }
    }
}
