        for (int i = 1; i <= n; i++) f[i] = nextInt(in);
        int[] ea = new int[m];
        int[] eb = new int[m];
        int[] outCnt = new int[n + 2];
        int[] inCnt = new int[n + 2];
        for (int i = 0; i < m; i++) {
            int a = nextInt(in);
            int b = nextInt(in);
            ea[i] = a;
            eb[i] = b;
            outCnt[a]++;
            inCnt[b]++;
        }
        int[] outStart = new int[n + 2];
        int[] inStart = new int[n + 2];
        for (int i = 1; i <= n; i++) {
            outStart[i + 1] = outStart[i] + outCnt[i];
            inStart[i + 1] = inStart[i] + inCnt[i];
        }
        int[] outPos = new int[n + 2];
        int[] inPos = new int[n + 2];
        for (int i = 1; i <= n + 1; i++) { outPos[i] = outStart[i]; inPos[i] = inStart[i]; }
        int[] adjOut = new int[m];
        int[] adjIn = new int[m];
        for (int i = 0; i < m; i++) {
            adjOut[outPos[ea[i]]++] = eb[i];
            adjIn[inPos[eb[i]]++] = ea[i];
        }

        boolean[] A = new boolean[n + 1];
        boolean[] B = new boolean[n + 1];
        int[] queue = new int[n + 1];

        int head = 0, tail = 0;
        for (int i = 1; i <= n; i++) {
            if (f[i] == 1) { A[i] = true; queue[tail++] = i; }
        }
        while (head < tail) {
            int u = queue[head++];
            for (int j = outStart[u]; j < outStart[u + 1]; j++) {
                int w = adjOut[j];
                if (f[w] != 1 && !A[w]) {
                    A[w] = true;
                    queue[tail++] = w;
                }
            }
        }

        head = 0; tail = 0;
        for (int i = 1; i <= n; i++) {
            if (f[i] == 2) { B[i] = true; queue[tail++] = i; }
        }
        while (head < tail) {
            int w = queue[head++];
            if (f[w] == 1) continue;
            for (int j = inStart[w]; j < inStart[w + 1]; j++) {
                int v = adjIn[j];
                if (!B[v]) {
                    B[v] = true;
                    queue[tail++] = v;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            sb.append((A[i] && B[i]) ? '1' : '0');
            sb.append('\n');
        }
        System.out.print(sb);
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int ret = 0;
        int b = in.read();
        while (b < '0' || b > '9') {
            if (b == -1) return -1;
            b = in.read();
        }
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = in.read();
        }
        return ret;
    }
}
