import java.io.*;

public class Main {
    static int n, k, root = 0;
    static int[] a, head, nxt, to, order, par, sz, dp, up;

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        n = nextInt(in);
        k = nextInt(in);
        a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt(in);
        head = new int[n];
        java.util.Arrays.fill(head, -1);
        nxt = new int[2 * (n - 1)];
        to = new int[2 * (n - 1)];
        int ec = 0;
        for (int i = 0; i < n - 1; i++) {
            int u = nextInt(in) - 1, v = nextInt(in) - 1;
            to[ec] = v; nxt[ec] = head[u]; head[u] = ec++;
            to[ec] = u; nxt[ec] = head[v]; head[v] = ec++;
        }
        order = new int[n]; par = new int[n]; sz = new int[n]; dp = new int[n]; up = new int[n];
        int[] st = new int[n];
        int sp = 0; st[sp++] = 0; par[0] = -1;
        int cnt = 0;
        while (sp > 0) {
            int v = st[--sp];
            order[cnt++] = v;
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int u = to[e];
                if (u != par[v]) { par[u] = v; st[sp++] = u; }
            }
        }
        java.util.Arrays.fill(sz, 1);
        for (int i = n - 1; i >= 1; i--) { int v = order[i]; sz[par[v]] += sz[v]; }
        int[] cand = a.clone();
        java.util.Arrays.sort(cand);
        int lo = 0, hi = n - 1, ans = cand[0];
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (check(cand[mid])) { ans = cand[mid]; lo = mid + 1; }
            else hi = mid - 1;
        }
        System.out.println(ans);
    }

    static boolean check(int x) {
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            if (a[v] < x) { dp[v] = 0; continue; }
            int sum = 1, best = 0;
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int u = to[e];
                if (u == par[v]) continue;
                if (dp[u] == sz[u]) sum += sz[u];
                else if (dp[u] > best) best = dp[u];
            }
            dp[v] = sum + best;
        }
        for (int i = 0; i < n; i++) {
            int p = order[i];
            int S = 0, M1 = 0, M2 = 0, bn = -1;
            if (p != root) {
                int usz = n - sz[p];
                if (up[p] == usz) S += usz;
                else {
                    if (up[p] > M1) { M2 = M1; M1 = up[p]; bn = -1; }
                    else if (up[p] > M2) M2 = up[p];
                }
            }
            for (int e = head[p]; e != -1; e = nxt[e]) {
                int c = to[e];
                if (c == par[p]) continue;
                if (dp[c] == sz[c]) S += sz[c];
                else {
                    if (dp[c] > M1) { M2 = M1; M1 = dp[c]; bn = c; }
                    else if (dp[c] > M2) M2 = dp[c];
                }
            }
            if (a[p] >= x && 1 + S + M1 >= k) return true;
            boolean pgood = a[p] >= x;
            for (int e = head[p]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (v == par[p]) continue;
                if (!pgood) { up[v] = 0; continue; }
                int Sp, m;
                if (dp[v] == sz[v]) { Sp = S - sz[v]; m = M1; }
                else { Sp = S; m = (bn == v) ? M2 : M1; }
                up[v] = 1 + Sp + m;
            }
        }
        return false;
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int ret = 0;
        int b = in.read();
        while (b < '0') b = in.read();
        while (b >= '0') { ret = ret * 10 + (b - '0'); b = in.read(); }
        return ret;
    }
}
