    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String s = br.readLine().trim();
        int m = s.length();

        int[] pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && s.charAt(i) != s.charAt(j)) j = pi[j - 1];
            if (s.charAt(i) == s.charAt(j)) j++;
            pi[i] = j;
        }

        int[][] delta = new int[m + 1][2];
        for (int q = 0; q <= m; q++) {
            for (int c = 0; c < 2; c++) {
                if (q < m && (s.charAt(q) - '0') == c) {
                    delta[q][c] = q + 1;
                } else if (q == 0) {
                    delta[q][c] = 0;
                } else {
                    delta[q][c] = delta[pi[q - 1]][c];
                }
            }
        }

        long answer = 0;
        for (int a = 0; a <= m; a++) {
            long[][] dp = new long[m + 1][2];
            dp[a][a == m ? 1 : 0] = 1;
            for (int step = 0; step < n; step++) {
                long[][] ndp = new long[m + 1][2];
                for (int q = 0; q <= m; q++) {
                    for (int f = 0; f < 2; f++) {
                        long cur = dp[q][f];
                        if (cur == 0) continue;
                        for (int c = 0; c < 2; c++) {
                            int nq = delta[q][c];
                            int nf = (f == 1 || nq == m) ? 1 : 0;
                            ndp[nq][nf] += cur;
                        }
                    }
                }
                dp = ndp;
            }
            answer += dp[a][1];
        }

        System.out.println(answer);
    }
}
