import java.util.*;
import java.io.*;

public class Main {
    static int N = 6;
    static long mod;

    static long[][] mul(long[][] a, long[][] b) {
        long[][] c = new long[N][N];
        for (int i = 0; i < N; i++)
            for (int k = 0; k < N; k++) {
                if (a[i][k] == 0) continue;
                long aik = a[i][k];
                for (int j = 0; j < N; j++) {
                    c[i][j] = (c[i][j] + aik * b[k][j]) % mod;
                }
            }
        return c;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        long sx = Long.parseLong(st.nextToken());
        long sy = Long.parseLong(st.nextToken());
        long dx = Long.parseLong(st.nextToken());
        long dy = Long.parseLong(st.nextToken());
        long t = Long.parseLong(st.nextToken());

        if (n == 1) {
            System.out.println("1 1");
            return;
        }
        mod = n;

        long x = ((sx - 1) % n + n) % n;
        long y = ((sy - 1) % n + n) % n;
        long ddx = ((dx % n) + n) % n;
        long ddy = ((dy % n) + n) % n;

        long[][] m = new long[N][N];
        // order: x, y, dx, dy, t, 1
        m[0] = new long[]{2,1,1,0,1,2};
        m[1] = new long[]{1,2,0,1,1,2};
        m[2] = new long[]{1,1,1,0,1,2};
        m[3] = new long[]{1,1,0,1,1,2};
        m[4] = new long[]{0,0,0,0,1,1};
        m[5] = new long[]{0,0,0,0,0,1};
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                m[i][j] %= mod;

        long[][] res = new long[N][N];
        for (int i = 0; i < N; i++) res[i][i] = 1 % mod;

        long e = t;
        while (e > 0) {
            if ((e & 1) == 1) res = mul(res, m);
            m = mul(m, m);
            e >>= 1;
        }

        long[] v = new long[]{x, y, ddx, ddy, 0, 1 % mod};
        long rx = 0, ry = 0;
        for (int j = 0; j < N; j++) {
            rx = (rx + res[0][j] * v[j]) % mod;
            ry = (ry + res[1][j] * v[j]) % mod;
        }
        System.out.println((rx + 1) + " " + (ry + 1));
    }
}
