import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int x = Integer.parseInt(st.nextToken());
        int pos = Integer.parseInt(st.nextToken());

        int left = 0, right = n;
        int cntLess = 0, cntGreater = 0;
        while (left < right) {
            int mid = (left + right) / 2;
            if (mid == pos) {
                left = mid + 1;
            } else if (mid < pos) {
                cntLess++;
                left = mid + 1;
            } else {
                cntGreater++;
                right = mid;
            }
        }

        int availLess = x - 1;
        int availGreater = n - x;
        if (cntLess > availLess || cntGreater > availGreater) {
            System.out.println(0);
            return;
        }
        long ans = 1;
        for (int i = 0; i < cntLess; i++) {
            ans = ans * ((availLess - i) % MOD) % MOD;
        }
        for (int i = 0; i < cntGreater; i++) {
            ans = ans * ((availGreater - i) % MOD) % MOD;
        }
        int rem = n - 1 - cntLess - cntGreater;
        for (int i = 1; i <= rem; i++) {
            ans = ans * i % MOD;
        }
        System.out.println(ans % MOD);
    }
}
