        long[][][][] dp = new long[5][5][12][12];
        for (int a = 1; a <= 4; a++)
            for (int b = 1; b <= 4; b++)
                if (a != b) dp[a][b][0][0] = 1;
        for (int i = 3; i <= n; i++) {
            long[][][][] nd = new long[5][5][12][12];
            for (int a = 1; a <= 4; a++)
                for (int b = 1; b <= 4; b++) {
                    if (a == b) continue;
                    for (int h = 0; h <= 10; h++)
                        for (int v = 0; v <= 10; v++) {
                            long cur = dp[a][b][h][v];
                            if (cur == 0) continue;
                            for (int c = 1; c <= 4; c++) {
                                if (c == b) continue;
                                int nh = h, nv = v;
                                if (a < b && b > c) nh++;
                                if (a > b && b < c) nv++;
                                if (nh > 10 || nv > 10) continue;
                                nd[b][c][nh][nv] += cur;
                            }
                        }
                }
            dp = nd;
        }
        long ans = 0;
        if (t - 1 >= 0) {
            for (int a = 1; a <= 4; a++)
                for (int b = 1; b <= 4; b++)
                    ans += dp[a][b][t][t - 1];
        }
        System.out.println(ans);
    }
