import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int w = Math.min(n, m);
        int h = Math.max(n, m);
        int full = (1 << w) - 1;
        int size = 1 << w;
        int[] f = new int[size];
        for (int mask = 0; mask < size; mask++) {
            f[mask] = (mask | (mask << 1) | (mask >> 1)) & full;
        }
        final int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[size][size];
        for (int[] row : dp) Arrays.fill(row, INF);
        dp[0][full] = 0;
        for (int r = 0; r < h; r++) {
            int[][] ndp = new int[size][size];
            for (int[] row : ndp) Arrays.fill(row, INF);
            for (int pm = 0; pm < size; pm++) {
                for (int cov = 0; cov < size; cov++) {
                    int cur = dp[pm][cov];
                    if (cur >= INF) continue;
                    for (int cm = 0; cm < size; cm++) {
                        if (((cov | cm) & full) != full) continue;
                        int newCov = (pm | f[cm]) & full;
                        int cost = cur + Integer.bitCount(cm);
                        if (cost < ndp[cm][newCov]) ndp[cm][newCov] = cost;
                    }
                }
            }
            dp = ndp;
        }
        int best = INF;
        for (int pm = 0; pm < size; pm++) {
            if (dp[pm][full] < best) best = dp[pm][full];
        }
        System.out.println(n * m - best);
    }
}
